    },
    {
      "activity_id": "A03",
      "activity_name": "U1 - Design Kafka changelog-backed repository",
      "activity_description": "Design the Spring Data repository abstraction over a local off-heap state store with Kafka changelog persistence, including topic layout, partitioning, and restore semantics.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A04",
      "activity_name": "U1 - Implement local off-heap state store",
      "activity_description": "Implement the RocksDB-based off-heap key/value store with serialization, iterators, and metrics for local data affinity.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A05",
      "activity_name": "U1 - Implement changelog sync and restore",
