      "most_likely_effort": 24
    },
    {
      "activity_id": "A08",
      "activity_name": "U2 - Design intelligent offset flush strategy",
      "activity_description": "Design correlation between consumed offsets and module-producer acknowledgements, flush thresholds, and error handling.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A09",
      "activity_name": "U2 - Implement ack-tracked offset manager",
      "activity_description": "Implement offset tracking gated on producer send callbacks, with batch/time-based asynchronous offset commits to Kafka.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A10",
      "activity_name": "U2 - Unit and integration tests",
      "activity_description": "Tests for ack-gated committing, at-least-once semantics on producer failure, and flush threshold behavior with embedded Kafka.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A11",
