      "activity_description": "Implement the Californium-based CoAP server endpoint (CON/NON, Observe), payload conversion, and emission onto the XD message bus with full configuration properties.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A16",
      "activity_name": "U4 - Unit and integration tests",
      "activity_description": "Tests using a Californium test client covering message types, content formats, error paths, and bus integration.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A17",
      "activity_name": "U5 - Deployment manifest properties documentation",
      "activity_description": "Write reference documentation (Asciidoc) with complete configuration property tables, defaults, and examples for the properties file used as the deployment manifest.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A18",
      "activity_name": "U6 - Kerberized HDFS test environment",
      "activity_description": "Stand up a MiniKDC-based kerberized HDFS mini-cluster for development and automated testing.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A19",
      "activity_name": "U6 - Implement secured Sqoop job support",
      "activity_description": "Implement Kerberos authentication (keytab, JAAS, UserGroupInformation.doAs) and Sqoop job configuration changes so jobs run against the secured HDFS cluster.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A20",
      "activity_name": "U6 - Unit and integration tests",
