      "most_likely_effort": 20
    },
    {
      "activity_id": "A21",
      "activity_name": "U7 - Design Java receptor client",
      "activity_description": "Design the client API surface for the Diego Receptor REST API: resources, DTO model, authentication, and error model.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A22",
      "activity_name": "U7 - Implement Java receptor client",
      "activity_description": "Implement the WebClient-based client covering Tasks, DesiredLRPs, ActualLRPs, Cells, and Domains endpoints, with DTOs, token auth, retries, and structured errors.",
      "most_likely_effort": 40
    },
    {
